import{_ as s,C as i,c,o as l,a3 as o,G as a,j as e,a as n}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Product configuration","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/products/product-configuration.md","filePath":"master/supply-chain/purchase/products/product-configuration.md","lastUpdated":1792041590000}'),u={name:"master/supply-chain/purchase/products/product-configuration.md"};function g(d,t,h,p,m,f){const r=i("ImagePopup");return l(),c("div",null,[t[0]||(t[0]=o('<h1 id="product-configuration" tabindex="-1">Product configuration <a class="header-anchor" href="#product-configuration" aria-label="Permalink to &quot;Product configuration&quot;">​</a></h1><p>Product configuration holds the shared lists that products and orders draw from. They are currencies, categories, attributes, packagings and unit categories. You set them up once, then pick them from drop-down lists when you work on products and orders.</p><blockquote><p><strong>In simple words:</strong> The small lists that describe your products and your money.</p></blockquote><p>Find them under <code>Purchase → Configurations</code>. Some entries depend on a setting.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry</th><th>Menu group</th><th>Needs</th></tr></thead><tbody><tr><td><strong>Currencies</strong></td><td>Purchase Orders</td><td>Nothing</td></tr><tr><td><strong>Categories</strong></td><td>Products</td><td>Nothing</td></tr><tr><td><strong>Attributes</strong></td><td>Products</td><td><strong>Variants</strong> on</td></tr><tr><td><strong>Packagings</strong></td><td>Products</td><td><strong>Packagings</strong> on</td></tr><tr><td><strong>UOM Categories</strong></td><td>Units of Measure</td><td>Nothing to open. Order lines show <strong>Unit</strong> only with <strong>Unit of Measure</strong> on</td></tr></tbody></table><p>Switch these on in <code>Purchase → Settings → Manage Products</code>. See <a href="./../get-started/purchase-settings.html">Purchase settings</a>.</p>',7)),a(r,{src:"/images1/purchase/cfg_menu.png",alt:"Configurations menu listing Vendor Price Lists, Currencies, Categories, Attributes, Packagings and UOM Categories"}),t[1]||(t[1]=e("h2",{id:"currencies",tabindex:"-1"},[n("Currencies "),e("a",{class:"header-anchor",href:"#currencies","aria-label":'Permalink to "Currencies"'},"​")],-1)),t[2]||(t[2]=e("p",null,[n("A currency lets you buy in the money your vendor uses. The order "),e("strong",null,"Currency"),n(" field lists the active ones.")],-1)),t[3]||(t[3]=e("ol",null,[e("li",null,[n("Go to "),e("code",null,"Purchase → Configurations → Currencies"),n(".")]),e("li",null,"Open a currency, or click the create button to add one.")],-1)),a(r,{src:"/images1/purchase/cfg_currency_form.png",alt:"Currency form with Currency Information, Format Configuration, Status and a Currency Rates table"}),t[4]||(t[4]=o('<ul><li><strong><em>Currency Name:</em></strong> The official code, for example EUR. Required.</li><li><strong><em>Currency Symbol:</em></strong> The sign shown with amounts.</li><li><strong><em>Full Name:</em></strong> The long name, for example Euro.</li><li><strong><em>ISO Numeric Code:</em></strong> The international number of the currency.</li><li><strong><em>Decimal Places:</em></strong> How many decimals amounts show. The default is 2.</li><li><strong><em>Rounding Precision:</em></strong> The step used to round amounts.</li><li><strong><em>Status:</em></strong> Active currencies appear in lists. Inactive ones do not.</li></ul><p>The <strong>Currency Rates</strong> table holds dated exchange rates against the base currency. Click to add a rate with a <strong>Date</strong> and a rate value.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Add a rate before you confirm an order in a foreign currency. Aureus converts vendor prices with it.</p></div><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>A category groups similar products, such as Laptops or Storage. Categories can be nested.</p><ol><li>Go to <code>Purchase → Configurations → Products → Categories</code>.</li><li>Click the create button.</li><li>Enter the <strong>Name</strong> and an optional <strong>Parent</strong>.</li></ol>',6)),a(r,{src:"/images1/purchase/cfg_category_form.png",alt:"Category form with name Storage and parent All"}),t[5]||(t[5]=o('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><p>Pick the category in the <strong>Category</strong> field of a product.</p><h2 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;Attributes&quot;">​</a></h2><p>An attribute describes a product by a choice, such as size or colour. Each value you add can make a variant.</p><ol><li>Go to <code>Purchase → Configurations → Products → Attributes</code>.</li><li>Click the create button.</li><li>Enter the <strong>Name</strong>, for example Capacity. Choose a <strong>Type</strong>.</li><li>In <strong>Options</strong>, add each value with its <strong>Name</strong>. Colour attributes also have a <strong>Color</strong>.</li><li>Enter an <strong>Extra Price</strong> if a value costs more.</li></ol>',5)),a(r,{src:"/images1/purchase/cfg_attribute_form.png",alt:"Attribute Capacity with options 256GB, 512GB and 1TB and extra prices"}),t[6]||(t[6]=o('<ol start="6"><li>Click <strong>Create</strong>.</li></ol><p>Attach attributes to a product on its <strong>Attributes</strong> page. See <a href="./configure-product.html">Configure a product</a>.</p><h2 id="packagings" tabindex="-1">Packagings <a class="header-anchor" href="#packagings" aria-label="Permalink to &quot;Packagings&quot;">​</a></h2><p>A packaging is a standard pack of a product, such as a box of 10. It helps you order whole packs.</p><ol><li>Go to <code>Purchase → Configurations → Products → Packagings</code>.</li><li>Click the create button. A window opens.</li><li>Fill the fields.</li></ol>',5)),a(r,{src:"/images1/purchase/cfg_packaging_form.png",alt:"Packaging window with name Box of 10, product Laptop Battery and quantity 10"}),t[7]||(t[7]=o('<ul><li><strong><em>Name:</em></strong> The packaging name. Required.</li><li><strong><em>Barcode:</em></strong> The barcode printed on the pack.</li><li><strong><em>Product:</em></strong> The product it packs. Required.</li><li><strong><em>Qty:</em></strong> Units per pack. Required.</li><li><strong><em>Company:</em></strong> The company that owns it.</li></ul><ol start="4"><li>Click <strong>Create</strong>.</li></ol><p>On an order line, <strong>Packaging Qty</strong> and <strong>Packaging</strong> appear. Aureus can match a line quantity to a pack, such as 20 units as 2 boxes of 10.</p><h2 id="units-of-measure" tabindex="-1">Units of measure <a class="header-anchor" href="#units-of-measure" aria-label="Permalink to &quot;Units of measure&quot;">​</a></h2><p>A unit category groups units that convert into each other, such as length or weight. Each unit has a ratio to the reference unit.</p><ol><li>Go to <code>Purchase → Configurations → Units of Measure → UOM Categories</code>.</li><li>Click the create button.</li><li>Enter the category <strong>Name</strong>.</li><li>Under <strong>Units of Measure</strong>, click <strong>Add Unit</strong> for each unit.</li></ol>',6)),a(r,{src:"/images1/purchase/cfg_uom_form.png",alt:"UOM category Weight with units Kilogram as reference and Gram as smaller"}),t[8]||(t[8]=o('<ul><li><strong><em>Unit of Measure:</em></strong> The unit name.</li><li><strong><em>Type:</em></strong> <strong>Reference</strong>, <strong>Bigger</strong> or <strong>Smaller</strong>. Each category needs exactly one <strong>Reference</strong> unit.</li><li><strong><em>Ratio:</em></strong> How the unit compares to the reference. It must be above zero.</li><li><strong><em>Rounding Precision:</em></strong> The step for rounding quantities. It must be above zero.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A category without a reference unit, or with two, cannot be saved.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../get-started/purchase-settings.html">Purchase settings</a></li><li><a href="./configure-product.html">Configure a product</a></li><li><a href="./../../inventories/products/units-of-measure.html">Units of measure in Inventory</a></li><li><a href="./../../inventories/products/attributes-and-packagings.html">Attributes and packagings in Inventory</a></li></ul>',4))])}const C=s(u,[["render",g]]);export{b as __pageData,C as default};
